{"cards": [{"node_code": "N_2d4a65368e93065f", "definition": "研究服务于公路交通的隧道工程，涵盖其线形设计、结构选型、通风照明、交通安全设施及运营维护等特定技术内容。", "boundary": "本节点聚焦于“公路”这一特定交通功能下的隧道。边界在于区分“公路隧道”与“城市地下隧道”（侧重城市综合管廊或地铁）、“穿山隧道”（侧重超长距离穿越山体）及“水底隧道”（侧重水下压力环境）。若内容仅涉及通用隧道力学，归入结构理论；若涉及公路隧道特有的交通组织与安全设计，归本节点。", "includes": ["公路隧道线形与断面设计", "公路隧道通风、照明及交通安全设施", "公路隧道运营管理与养护技术"], "excludes": ["城市地铁或综合管廊隧道", "水底隧道专用防水与压力技术", "通用隧道结构力学理论"], "sibling_distinctions": [{"other_code": "N_9e0a550b1e980124", "rule": "公路隧道侧重服务于公路交通的线性通道；地下隧道侧重城市地下空间、地铁或综合管廊等复杂环境下的隧道系统。"}, {"other_code": "N_86f5c8f6db835e3c", "rule": "公路隧道是功能分类，穿山隧道是地质/地形分类。若强调穿越山体的超长距离与地质难点，归穿山隧道；若强调公路交通功能，归本节点。"}, {"other_code": "N_a7b8f046d25a3dc8", "rule": "公路隧道在陆地路面下；水底隧道在水体下，涉及水压与防水特殊技术。"}], "cross_boundary_rule": "若内容涉及“公路穿山隧道”，侧重交通功能与运营归本节点，侧重超长隧道地质施工难点可关联穿山隧道。"}, {"node_code": "N_9e0a550b1e980124", "definition": "研究城市及复杂地下环境中的隧道工程，涵盖地铁、综合管廊、地下通道等地下空间隧道的规划、结构、施工及多系统协同技术。", "boundary": "本节点聚焦于“地下空间”及“城市环境”下的隧道。边界在于区分“地下隧道”与“公路隧道”（侧重城市综合功能与地下空间利用）、“穿山隧道”（侧重山体穿越）。若内容涉及城市地铁隧道土建，归本节点；若涉及地铁运营，归交通工程。", "includes": ["城市地铁、轻轨等轨道交通隧道", "城市综合管廊及地下公用隧道", "城市地下人行通道及地下空间隧道"], "excludes": ["单纯服务于公路的隧道（归公路隧道）", "水底隧道（归水底隧道）", "矿山巷道（归矿业工程）"], "sibling_distinctions": [{"other_code": "N_2d4a65368e93065f", "rule": "地下隧道侧重城市地下空间利用与多系统协同（如地铁、管廊）；公路隧道侧重公路交通线性通道。"}, {"other_code": "N_86f5c8f6db835e3c", "rule": "地下隧道侧重城市浅埋或复杂环境；穿山隧道侧重山体深埋或超长距离穿越。"}], "cross_boundary_rule": "若内容涉及“城市地下公路隧道”，侧重城市地下空间规划归本节点，侧重公路交通功能归公路隧道。"}, {"node_code": "N_86f5c8f6db835e3c", "definition": "研究穿越山体、丘陵等复杂地形地带的隧道工程，涵盖长距离穿越、高地应力、不良地质处理及超长隧道施工运营技术。", "boundary": "本节点聚焦于“穿山”这一特定地形/地质条件下的隧道。边界在于区分“穿山隧道”与“公路隧道”（功能分类）、“地下隧道”（城市环境）。若内容强调穿越山体的地质难点、高地应力或超长距离，归本节点；若仅强调公路功能，归公路隧道。", "includes": ["超长隧道（如>10km）设计与施工", "高地应力、岩爆、涌水等不良地质处理", "穿山隧道通风、救援及运营安全"], "excludes": ["城市浅埋隧道（归地下隧道）", "水底隧道（归水底隧道）", "通用隧道结构理论"], "sibling_distinctions": [{"other_code": "N_2d4a65368e93065f", "rule": "穿山隧道侧重地形地质难点（如超长、高地应力）；公路隧道侧重交通功能。若隧道穿越山体且强调地质难点，归本节点。"}, {"other_code": "N_9e0a550b1e980124", "rule": "穿山隧道侧重山体穿越；地下隧道侧重城市地下空间。"}], "cross_boundary_rule": "若内容涉及“公路穿山隧道”，侧重地质施工难点归本节点，侧重交通运营归公路隧道。"}]}
